package com.godjiismp.skills;

import net.fabricmc.fabric.api.entity.event.v1.ServerLivingEntityEvents;import net.fabricmc.fabric.api.event.lifecycle.v1.ServerTickEvents;import net.fabricmc.fabric.api.event.player.PlayerBlockBreakEvents;import net.minecraft.core.BlockPos;import net.minecraft.core.registries.BuiltInRegistries;import net.minecraft.resources.ResourceLocation;import net.minecraft.server.MinecraftServer;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.entity.Entity;import net.minecraft.world.entity.ai.attributes.AttributeModifier;import net.minecraft.world.entity.ai.attributes.Attributes;import net.minecraft.world.entity.item.ItemEntity;import net.minecraft.world.entity.monster.Monster;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.ItemStack;import net.minecraft.world.item.Items;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.Block;import net.minecraft.world.level.block.Blocks;import net.minecraft.world.level.block.CropBlock;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.phys.AABB;

public final class SkillHooks {private SkillHooks(){}private static final ResourceLocation WALK_ID=ResourceLocation.fromNamespaceAndPath("godjiismp_newdays","exploration_walk");private record BreakSnapshot(java.util.Set<java.util.UUID> items,long tick){}private static final java.util.Map<String,BreakSnapshot> PRE_BREAK_ITEMS=new java.util.HashMap<>();
 public static void init(){ServerLivingEntityEvents.AFTER_DEATH.register(SkillHooks::onKill);ServerLivingEntityEvents.AFTER_DAMAGE.register(SkillHooks::onDamaged);PlayerBlockBreakEvents.BEFORE.register((world,player,pos,state,blockEntity)->{if(player instanceof ServerPlayer){String k=key(world,player,pos);PRE_BREAK_ITEMS.put(k,new BreakSnapshot(world.getEntitiesOfClass(ItemEntity.class,new AABB(pos).inflate(1.35)).stream().map(Entity::getUUID).collect(java.util.stream.Collectors.toSet()),world.getGameTime()));}return true;});PlayerBlockBreakEvents.AFTER.register(SkillHooks::onBreak);ServerTickEvents.END_SERVER_TICK.register(SkillHooks::tick);}
 private static void onKill(net.minecraft.world.entity.LivingEntity target,net.minecraft.world.damagesource.DamageSource source){Entity a=source.getEntity();if(a instanceof net.minecraft.world.entity.projectile.Projectile p)a=p.getOwner();if(a instanceof ServerPlayer player&&target instanceof Monster&&Skills.level(player,0)>=10)player.heal((float)SkillsConfig.monsterKillHeal);}
 private static void onDamaged(net.minecraft.world.entity.LivingEntity target,net.minecraft.world.damagesource.DamageSource source,float base,float dealt,float blocked){if(!(target instanceof ServerPlayer p)||p.isDeadOrDying())return;int lv=Skills.level(p,1);if(lv<10||p.getHealth()>p.getMaxHealth()*SkillsConfig.lowHealthThreshold)return;SkillData data=SkillData.get(p.getServer());SkillData.Entry e=data.entry(p.getUUID());long now=p.serverLevel().getGameTime(),cd=SkillsConfig.defenseHealCooldownSeconds*20L;if(now<e.defenseHealAt)return;e.defenseHealAt=now+cd;data.changed();p.heal((float)SkillsConfig.lowHealthHeal);}
 private static void onBreak(Level world,Player player,BlockPos pos,BlockState state,net.minecraft.world.level.block.entity.BlockEntity blockEntity){if(!(player instanceof ServerPlayer p)||world.isClientSide)return;BreakSnapshot snapshot=PRE_BREAK_ITEMS.remove(key(world,player,pos));java.util.Set<java.util.UUID> prior=snapshot==null?java.util.Set.of():snapshot.items();int mining=Skills.level(p,2);if(mining>=SkillsConfig.miningAutoPickupLevel){AABB box=new AABB(pos).inflate(1.35);for(ItemEntity drop:world.getEntitiesOfClass(ItemEntity.class,box,d->!prior.contains(d.getUUID()))){ItemStack rest=drop.getItem().copy();p.getInventory().add(rest);if(rest.isEmpty())drop.discard();else drop.setItem(rest);}}
  int farming=Skills.level(p,3);if(farming>=SkillsConfig.farmingReplantLevel&&state.getBlock() instanceof CropBlock crop&&state.getValue(CropBlock.AGE)>=crop.getMaxAge()){ItemStack seed=state.is(Blocks.WHEAT)?new ItemStack(Items.WHEAT_SEEDS):state.is(Blocks.CARROTS)||state.is(Blocks.POTATOES)?new ItemStack(state.is(Blocks.POTATOES)?Items.POTATO:Items.CARROT):state.is(Blocks.BEETROOTS)?new ItemStack(Items.BEETROOT_SEEDS):ItemStack.EMPTY;if(!seed.isEmpty()&&!p.isCreative()&&removeOne(p,seed)){world.setBlock(pos,crop.getStateForAge(0),Block.UPDATE_ALL);}}
 }
 private static boolean removeOne(ServerPlayer p,ItemStack sample){for(ItemStack s:p.getInventory().items)if(ItemStack.isSameItem(s,sample)){s.shrink(1);return true;}return false;}
 private static String key(Level world,Player player,BlockPos pos){return world.dimension().location()+":"+player.getUUID()+":"+pos.asLong();}
 private static void tick(MinecraftServer server){long time=server.overworld().getGameTime();for(var it=PRE_BREAK_ITEMS.entrySet().iterator();it.hasNext();)if(time-it.next().getValue().tick()>80)it.remove();if(time%SkillsConfig.skillTickIntervalTicks!=0)return;for(ServerPlayer p:server.getPlayerList().getPlayers()){var attr=p.getAttribute(Attributes.MOVEMENT_SPEED);if(attr!=null){attr.removeModifier(WALK_ID);int level=Skills.level(p,5);if(level>0)attr.addTransientModifier(new AttributeModifier(WALK_ID,level*SkillsConfig.walkPerLevel,AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL));}if(Skills.level(p,4)>0&&(p.getMainHandItem().is(Items.FISHING_ROD)||p.getOffhandItem().is(Items.FISHING_ROD)))p.addEffect(new net.minecraft.world.effect.MobEffectInstance(net.minecraft.world.effect.MobEffects.LUCK,SkillsConfig.fishingEffectDurationTicks,SkillsConfig.fishingLuckAmplifier,true,false,true));if(Skills.level(p,3)>=SkillsConfig.farmingGrowthLevel&&p.serverLevel().random.nextDouble()<SkillsConfig.farmlandGrowthChance){int r=(int)Math.ceil(SkillsConfig.farmlandRadius);BlockPos pos=p.blockPosition().offset(p.serverLevel().random.nextInt(-r,r+1),p.serverLevel().random.nextInt(-r,r+1),p.serverLevel().random.nextInt(-r,r+1));BlockState state=p.serverLevel().getBlockState(pos);if(state.getBlock() instanceof CropBlock crop&&state.getValue(CropBlock.AGE)<crop.getMaxAge())p.serverLevel().setBlock(pos,crop.getStateForAge(state.getValue(CropBlock.AGE)+1),Block.UPDATE_CLIENTS);}}
 }
}


